// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address target, uint256 value, bytes calldata data) public {
        vm.assume(target != address(0));
        vm.assume(target != address(c));
        vm.assume(value <= address(this).balance);

        uint256 depositsBefore = c.depositsCount();

        vm.prank(c.owner());
        c.sendMoney(target, value, data);

        assertTrue(c.depositsCount() == depositsBefore);
    }
}
